/* \u0628\u0646\u0631\u0647\u0627\u06CC \u06AF\u0631\u0627\u062F\u06CC\u0627\u0646 \u0622\u0628\u06CC (\u0628\u0646\u0631 \u0628\u0631\u0646\u062F \u062F\u0627\u0634\u0628\u0648\u0631\u062F \u0648\u2026) */
